const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.participantId != null);
const inputs = $('Webhook').first().json.body.participants || [];
const grouped = new Map();
for (const row of rows) {
  const idx = row.inputIndex;
  if (!grouped.has(idx)) grouped.set(idx, []);
  const { inputIndex, ...rest } = row;
  grouped.get(idx).push(rest);
}
const results = inputs.map((input, i) => ({
  inputIndex: i,
  input,
  matches: grouped.get(i) ?? [],
}));
return [{ json: { results } }];

const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.email && r.tripId && r.buyerId);

const candidates = rows.slice(0, 20).map((r) => {
  const fullName = [r.firstName, r.lastName].filter(Boolean).join(' ').trim();
  const candidate = {
    name: fullName || r.email,
    email: r.email,
  };
  if (r.chapterName) candidate.school = r.chapterName;
  return candidate;
});

return [{ json: { candidates } }];

